import React from 'react';
import { Row, TableInstance } from 'react-table';
import type { Hooks } from 'react-table';

import type {
  SingleThreshold,
  Threshold,
  ThresholdExtended,
  ThresholdColors,
} from '../../../core/types/threshold-types.js';
import {
  _checkCombinedThresholdRules,
  _matchesThreshold,
} from '../../../core/utils/threshold-utils.js';

/* eslint-disable @typescript-eslint/no-explicit-any */

/**
 * Returns the threshold color to be used for a given row or `null` if no row highlighting
 * is enabled or no values matches a configured threshold.
 * @param row - row information to get values to compare
 * @param forBackgroundColor - if this is for background color
 * @returns the color of the threshold configuration
 *
 * @internal
 */
export function _getThresholdColors(
  row: Row<any>,
  thresholds: ThresholdExtended[],
): ThresholdColors {
  const allRowAccessors = Object.keys(row.values);
  for (let i = thresholds.length - 1; i >= 0; i--) {
    const combinedRules = thresholds[i].rules;
    const color = thresholds[i].color;
    const backgroundColor = thresholds[i].backgroundColor;
    // If combined thresholds rules are defined. */
    if (combinedRules) {
      return _checkCombinedThresholdRules(
        combinedRules,
        allRowAccessors,
        row.values,
        color,
        backgroundColor,
      );
    } else {
      // assert: no rules so it must be a single row threshold
      const singleRule = thresholds[i] as SingleThreshold;
      const foundAccessor = allRowAccessors.find(
        (key) => singleRule.id === key,
      );

      if (foundAccessor) {
        const thresholdColor = _matchesThreshold(
          row.values[foundAccessor],
          thresholds[i] as Threshold,
        );

        if (thresholdColor) {
          return {
            thresholdColor: color,
            thresholdBackgroundColor: backgroundColor,
          };
        }
      } else {
        return {
          thresholdColor: undefined,
          thresholdBackgroundColor: undefined,
        };
      }
    }
  }
  return { thresholdColor: undefined, thresholdBackgroundColor: undefined };
}

/**
 * Returns the object with defined color and backgroundColor of the threshold configuration that matches a given value or
 * object containing undefined values if no threshold matches.
 *
 * @param value - The value to compare the threshold value(s) to
 * @param thresholds - The thresholds to test the value against
 * @param colorFn - Function that gets called whenever a value matches a threshold
 * @returns the threshold colors for that value
 *
 * TO DO: This function will be removed. Follow-up : ADES-6156
 */
export function getThresholdColorForCell(
  value: number | string,
  thresholds: Threshold[],
  colorFn?: (threshold: Threshold) => ThresholdColors,
): ThresholdColors {
  for (let i = thresholds.length - 1; i >= 0; i--) {
    const threshold = thresholds[i];

    if (_matchesThreshold(value, threshold)) {
      if (colorFn) {
        colorFn(threshold);
      }
      const color = threshold.color;
      const bgColor = threshold.backgroundColor;

      return { thresholdColor: color, thresholdBackgroundColor: bgColor };
    }
  }

  return { thresholdColor: undefined, thresholdBackgroundColor: undefined };
}

/** Installs hooks for applying the correct highlight color for rows and cell as CSS variables. */
function applyCellHighlightColors(instance: TableInstance<any>): void {
  const { getHooks } = instance;

  getHooks().getCellProps.push((props, { cell }) => {
    if (cell.column.thresholds) {
      const { thresholdColor, thresholdBackgroundColor } =
        getThresholdColorForCell(cell.value, cell.column.thresholds);

      if (thresholdColor || thresholdBackgroundColor) {
        const styleObject: React.CSSProperties = {};

        if (thresholdColor) {
          styleObject['--strato-table-cell-highlight-color'] = thresholdColor;
        }

        if (thresholdBackgroundColor) {
          styleObject['--strato-table-cell-highlight-background-color'] =
            thresholdBackgroundColor;
        }

        return [
          props,
          {
            style: styleObject,
          },
        ];
      }
    }

    return props;
  });
}

/** Installs hooks for applying the correct highlight color for rows and cell as CSS variables. */
function applyRowHighlightColors(instance: TableInstance<any>): void {
  const { getHooks } = instance;
  if (instance.rowThresholds) {
    getHooks().getRowProps.push((props, { row }) => {
      const { thresholdColor, thresholdBackgroundColor } = _getThresholdColors(
        row,
        instance.rowThresholds as ThresholdExtended[],
      );
      // if either one of them has a value
      if (
        (thresholdColor && !thresholdBackgroundColor) ||
        (!thresholdColor && thresholdBackgroundColor)
      ) {
        const styleObject: React.CSSProperties = {};
        styleObject[
          thresholdColor
            ? '--strato-table-row-highlight-color'
            : '--strato-table-row-highlight-background-color'
        ] = thresholdColor ? thresholdColor : thresholdBackgroundColor;
        return [
          props,
          {
            key: `strato-table-row-highlight-color-row-${row.id}`,
            style: styleObject,
          },
        ];
      } else if (thresholdColor && thresholdBackgroundColor) {
        // if both values exist
        // in this case update font color at cell level instead of the pill
        row.cells.forEach((cell) => {
          // Modify cell props
          const cellProps = {
            ...cell.getCellProps(),
            style: {
              ...(cell.getCellProps().style || {}),
              // Add cell-level styles based on yourRowValue
              '--strato-table-cell-highlight-color': thresholdColor,
            },
          };
          // Apply the modified cell props back to the cell
          cell.getCellProps = () => cellProps;
        });
        return [
          props,
          {
            key: `strato-table-row-highlight-color-row-${row.id}`,
            style: {
              '--strato-table-row-highlight-background-color':
                thresholdBackgroundColor,
            } as React.CSSProperties,
          },
        ];
      }
      return props;
    });
  }
}

/** Table hook that enables threshold highlighting for cells and rows. */
export function useThresholds(hooks: Hooks): void {
  hooks.useInstance.push(applyCellHighlightColors);
  hooks.useInstance.push(applyRowHighlightColors);
}
